//! JSON Schema (as emitted by schemars for `genie-protocol`) → TypeScript (02 §11).
//!
//! Handles the subset schemars produces: `$ref`, `const`, `enum`, `oneOf`/`anyOf`,
//! `type` (string or array), `properties`/`required`, `additionalProperties`, `items`
//! and the boolean schemas.

use std::collections::BTreeMap;
use std::fmt::Write as _;

use serde_json::{Map, Value};

pub const HEADER: &str =
    "// Generated by `cargo xtask schema` from crates/genie-protocol. Do not edit.\n";

fn ref_name(r: &str) -> &str {
    r.rsplit('/').next().unwrap_or(r)
}

fn paren(t: String) -> String {
    if t.contains(" | ") || t.contains(" & ") {
        format!("({t})")
    } else {
        t
    }
}

fn is_ident(s: &str) -> bool {
    let mut c = s.chars();
    c.next()
        .is_some_and(|f| f.is_ascii_alphabetic() || f == '_' || f == '$')
        && c.all(|x| x.is_ascii_alphanumeric() || x == '_' || x == '$')
}

fn prop_key(k: &str) -> String {
    if is_ident(k) {
        k.to_string()
    } else {
        format!("{k:?}")
    }
}

fn doc(out: &mut String, indent: &str, schema: &Value) {
    if let Some(d) = schema.get("description").and_then(Value::as_str) {
        let d = d.replace("*/", "* /");
        if d.contains('\n') {
            let _ = writeln!(out, "{indent}/**");
            for l in d.lines() {
                let _ = writeln!(out, "{indent} * {l}");
            }
            let _ = writeln!(out, "{indent} */");
        } else {
            let _ = writeln!(out, "{indent}/** {d} */");
        }
    }
}

fn primitive(t: &str, schema: &Value) -> String {
    match t {
        "string" => "string".into(),
        "integer" | "number" => "number".into(),
        "boolean" => "boolean".into(),
        "null" => "null".into(),
        "array" => match schema.get("items") {
            Some(i) => format!("{}[]", paren(ts_type(i))),
            None => "unknown[]".into(),
        },
        "object" => object_type(schema),
        _ => "unknown".into(),
    }
}

fn object_type(schema: &Value) -> String {
    let props = schema.get("properties").and_then(Value::as_object);
    let extra = schema.get("additionalProperties");
    match (props, extra) {
        (Some(p), _) if !p.is_empty() => inline_object(p, required(schema)),
        (_, Some(Value::Bool(false))) => "Record<string, never>".into(),
        (_, Some(e)) if !e.is_boolean() => format!("Record<string, {}>", ts_type(e)),
        _ => "Record<string, unknown>".into(),
    }
}

fn required(schema: &Value) -> Vec<String> {
    schema
        .get("required")
        .and_then(Value::as_array)
        .map(|a| {
            a.iter()
                .filter_map(|v| v.as_str().map(String::from))
                .collect()
        })
        .unwrap_or_default()
}

fn inline_object(props: &Map<String, Value>, req: Vec<String>) -> String {
    let fields: Vec<String> = props
        .iter()
        .map(|(k, v)| {
            let opt = if req.contains(k) { "" } else { "?" };
            format!("{}{opt}: {}", prop_key(k), ts_type(v))
        })
        .collect();
    format!("{{ {} }}", fields.join("; "))
}

/// The TypeScript type expression for a schema.
pub fn ts_type(schema: &Value) -> String {
    match schema {
        Value::Bool(true) => return "unknown".into(),
        Value::Bool(false) => return "never".into(),
        _ => {}
    }
    if let Some(c) = schema.get("const") {
        return c.to_string();
    }
    if let Some(e) = schema.get("enum").and_then(Value::as_array) {
        return e
            .iter()
            .map(Value::to_string)
            .collect::<Vec<_>>()
            .join(" | ");
    }
    for k in ["oneOf", "anyOf"] {
        if let Some(alts) = schema.get(k).and_then(Value::as_array) {
            let mut v: Vec<String> = alts.iter().map(|a| paren(ts_type(a))).collect();
            v.dedup();
            return v.join(" | ");
        }
    }
    if let Some(r) = schema.get("$ref").and_then(Value::as_str) {
        let name = ref_name(r).to_string();
        // Internally tagged newtype variant: `$ref` + the tag property.
        return match schema.get("properties").and_then(Value::as_object) {
            Some(p) if !p.is_empty() => format!("{} & {name}", inline_object(p, required(schema))),
            _ => name,
        };
    }
    match schema.get("type") {
        Some(Value::String(t)) => primitive(t, schema),
        Some(Value::Array(ts)) => ts
            .iter()
            .filter_map(Value::as_str)
            .map(|t| paren(primitive(t, schema)))
            .collect::<Vec<_>>()
            .join(" | "),
        _ if schema.get("properties").is_some() => object_type(schema),
        _ => "unknown".into(),
    }
}

/// `types.ts`: one declaration per `$defs` entry.
pub fn types_file(defs: &Map<String, Value>) -> String {
    let mut out = String::from(HEADER);
    for (name, schema) in defs {
        out.push('\n');
        doc(&mut out, "", schema);
        let props = schema.get("properties").and_then(Value::as_object);
        let plain_object = schema.get("type").and_then(Value::as_str) == Some("object")
            && props.is_some_and(|p| !p.is_empty())
            && schema.get("$ref").is_none()
            && schema.get("oneOf").is_none()
            && schema.get("anyOf").is_none();
        match props {
            Some(p) if plain_object => {
                let req = required(schema);
                let _ = writeln!(out, "export interface {name} {{");
                for (k, v) in p {
                    doc(&mut out, "  ", v);
                    let opt = if req.contains(k) { "" } else { "?" };
                    let _ = writeln!(out, "  {}{opt}: {};", prop_key(k), ts_type(v));
                }
                out.push_str("}\n");
            }
            _ => {
                let _ = writeln!(out, "export type {name} = {};", ts_type(schema));
            }
        }
    }
    out
}

#[derive(Default)]
struct Node {
    leaf: Option<(String, String, String)>, // (wire name, params, result)
    children: BTreeMap<String, Node>,
}

fn emit_node(out: &mut String, node: &Node, indent: usize) -> Result<(), String> {
    let pad = "  ".repeat(indent);
    for (k, child) in &node.children {
        match (&child.leaf, child.children.is_empty()) {
            (Some((wire, p, r)), true) => {
                let default = if p == "T.Empty" { " = {}" } else { "" };
                let call = format!(
                    "(params: {p}{default}): Promise<{r}> => this.t.request({wire:?}, params) as Promise<{r}>"
                );
                let _ = writeln!(out, "{pad}{}: {call},", prop_key(k));
            }
            (None, false) => {
                let _ = writeln!(out, "{pad}{}: {{", prop_key(k));
                emit_node(out, child, indent + 1)?;
                let _ = writeln!(out, "{pad}}},");
            }
            _ => {
                return Err(format!(
                    "method name `{k}` is both a method and a namespace"
                ));
            }
        }
    }
    Ok(())
}

/// `methods.ts`: method maps, the method table and a typed client stub.
pub fn methods_file(methods: &[Value]) -> Result<String, String> {
    let mut out = String::from(HEADER);
    out.push_str("\nimport type * as T from \"./types\";\n");
    let mut sections: BTreeMap<&str, Vec<String>> = BTreeMap::new();
    let mut root = Node::default();
    let mut table = String::new();
    for m in methods {
        let name = m["name"].as_str().unwrap_or_default();
        let dir = m["direction"].as_str().unwrap_or_default();
        let p = qualify(&ts_type(&m["params"]));
        let r = qualify(&ts_type(&m["result"]));
        let _ = writeln!(
            table,
            "  {{ name: {name:?}, direction: {dir:?}, needsLease: {} }},",
            m["needs_lease"].as_bool().unwrap_or(false)
        );
        match dir {
            "request" => {
                sections
                    .entry("Requests")
                    .or_default()
                    .push(format!("  {name:?}: {{ params: {p}; result: {r} }};"));
                let path: Vec<&str> = match name {
                    "$/ping" => vec!["ping"],
                    n => n.split('.').collect(),
                };
                let mut node = &mut root;
                for seg in path {
                    node = node.children.entry(seg.to_string()).or_default();
                }
                node.leaf = Some((name.to_string(), p.clone(), r.clone()));
            }
            "server_request" => sections
                .entry("ServerRequests")
                .or_default()
                .push(format!("  {name:?}: {{ params: {p}; result: {r} }};")),
            "notification" => sections
                .entry("Notifications")
                .or_default()
                .push(format!("  {name:?}: {p};")),
            _ => sections
                .entry("ClientNotifications")
                .or_default()
                .push(format!("  {name:?}: {p};")),
        }
    }
    for s in [
        "Requests",
        "ServerRequests",
        "Notifications",
        "ClientNotifications",
    ] {
        let _ = writeln!(out, "\nexport interface {s} {{");
        for l in sections.get(s).map(Vec::as_slice).unwrap_or_default() {
            let _ = writeln!(out, "{l}");
        }
        out.push_str("}\n");
    }
    out.push_str(
        "\nexport type MethodDirection = \"request\" | \"server_request\" | \"notification\" | \"client_notification\";\n",
    );
    let _ = write!(
        out,
        "\nexport const METHODS: readonly {{ name: string; direction: MethodDirection; needsLease: boolean }}[] = [\n{table}];\n"
    );
    out.push_str(
        "\n/** Sends a JSON-RPC request and resolves with its result (the Tauri relay or a test transport). */\n\
         export interface Transport {\n  request(method: string, params: unknown): Promise<unknown>;\n}\n\
         \n/** Typed client stub: `client.session.prompt({...})`. */\n\
         export class GenieClient {\n  constructor(private readonly t: Transport) {}\n\n",
    );
    for (k, child) in &root.children {
        match (&child.leaf, child.children.is_empty()) {
            (Some((wire, p, r)), true) => {
                let default = if p == "T.Empty" { " = {}" } else { "" };
                let _ = writeln!(
                    out,
                    "  readonly {} = (params: {p}{default}): Promise<{r}> => this.t.request({wire:?}, params) as Promise<{r}>;",
                    prop_key(k)
                );
            }
            _ => {
                let _ = writeln!(out, "  readonly {} = {{", prop_key(k));
                emit_node(&mut out, child, 2)?;
                out.push_str("  };\n");
            }
        }
    }
    out.push_str("}\n");
    out.push_str(
        "\n/** Discriminant of a session event (02 §4). Unknown types must be ignored (02 §10). */\n\
         export type SessionEventType = T.SessionEvent[\"type\"];\n",
    );
    Ok(out)
}

/// Prefix named types with the `T.` namespace import.
fn qualify(t: &str) -> String {
    let mut out = String::new();
    let mut word = String::new();
    let mut in_str = false;
    let flush = |word: &mut String, out: &mut String| {
        if !word.is_empty() {
            let builtin = matches!(
                word.as_str(),
                "string" | "number" | "boolean" | "null" | "unknown" | "never" | "Record"
            );
            if !builtin && word.chars().next().is_some_and(|c| c.is_ascii_uppercase()) {
                out.push_str("T.");
            }
            out.push_str(word);
            word.clear();
        }
    };
    for c in t.chars() {
        if c == '"' {
            flush(&mut word, &mut out);
            in_str = !in_str;
            out.push(c);
        } else if !in_str && (c.is_ascii_alphanumeric() || c == '_') {
            word.push(c);
        } else {
            flush(&mut word, &mut out);
            out.push(c);
        }
    }
    flush(&mut word, &mut out);
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn shapes() {
        assert_eq!(
            ts_type(&json!({"type": ["string", "null"]})),
            "string | null"
        );
        assert_eq!(ts_type(&json!({"enum": ["a", "b"]})), "\"a\" | \"b\"");
        assert_eq!(
            ts_type(&json!({"type": "array", "items": {"$ref": "#/$defs/X"}})),
            "X[]"
        );
        assert_eq!(
            ts_type(
                &json!({"$ref": "#/$defs/X", "properties": {"type": {"const": "x"}}, "required": ["type"]})
            ),
            "{ type: \"x\" } & X"
        );
        assert_eq!(
            ts_type(&json!({"type": "object", "additionalProperties": {"type": "string"}})),
            "Record<string, string>"
        );
        assert_eq!(
            qualify("{ type: \"Text\" } & Ask[]"),
            "{ type: \"Text\" } & T.Ask[]"
        );
    }
}
